-- ไฟล์นี้รันได้อิสระ ไม่ต้องพึ่งไฟล์อื่น (idempotent)
-- ============================================================

begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'wireless_satellite', 'ระบบสื่อสารไร้สายและดาวเทียม (Wireless & Satellite Communication)', 17
where not exists (
  select 1 from categories where branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and code = 'wireless_satellite'
);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'คลื่นวิทยุ (Radio Wave) เดินทางผ่านอากาศได้อย่างไร และมีปัจจัยใดบ้างที่ส่งผลต่อระยะทางการสื่อสาร', 'คลื่นวิทยุเป็นคลื่นแม่เหล็กไฟฟ้าที่เดินทางผ่านอากาศหรือสุญญากาศได้โดยไม่ต้องอาศัยตัวกลาง ระยะทางการสื่อสารได้รับผลกระทบจากหลายปัจจัย เช่น กำลังส่งสัญญาณ ความถี่ที่ใช้ สิ่งกีดขวางระหว่างทาง สภาพภูมิประเทศ และความไวของเครื่องรับสัญญาณ', 'ความถี่ที่แตกต่างกันมีคุณสมบัติการเดินทางที่แตกต่างกัน เช่น ความถี่ต่ำสามารถเลี้ยวเบนผ่านสิ่งกีดขวางได้ดีกว่าแต่รองรับแบนด์วิดท์น้อยกว่า ในขณะที่ความถี่สูงรองรับแบนด์วิดท์มากกว่าแต่ถูกบดบังจากสิ่งกีดขวางได้ง่ายกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'คลื่นวิทยุ (Radio Wave) เดินทางผ่านอากาศได้อย่างไร และมีปัจจัยใดบ้างที่ส่งผลต่อระยะทางการสื่อสาร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เสาอากาศ (Antenna) ในระบบสื่อสารไร้สายทำหน้าที่อะไร และมีหลักการทำงานพื้นฐานอย่างไร', 'ทำหน้าที่แปลงสัญญาณไฟฟ้าให้เป็นคลื่นแม่เหล็กไฟฟ้าที่แผ่กระจายออกไปในอากาศ (ในโหมดส่ง) หรือรับคลื่นแม่เหล็กไฟฟ้าที่เดินทางมาแล้วแปลงกลับเป็นสัญญาณไฟฟ้า (ในโหมดรับ) โดยอาศัยหลักการที่กระแสไฟฟ้าที่เปลี่ยนแปลงตามเวลาในตัวนำสามารถสร้างคลื่นแม่เหล็กไฟฟ้าแผ่กระจายออกไปได้ และในทางกลับกันคลื่นแม่เหล็กไฟฟ้าที่ตกกระทบตัวนำสามารถเหนี่ยวนำให้เกิดกระแสไฟฟ้าได้เช่นกัน', 'ขนาดและรูปทรงของเสาอากาศต้องออกแบบให้สอดคล้องกับความยาวคลื่นของความถี่ที่ใช้งาน เพื่อให้ได้ประสิทธิภาพการส่งและรับสัญญาณที่ดีที่สุด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เสาอากาศ (Antenna) ในระบบสื่อสารไร้สายทำหน้าที่อะไร และมีหลักการทำงานพื้นฐานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'อัตราขยายของเสาอากาศ (Antenna Gain) มีความหมายอย่างไร และเสาอากาศแบบทิศทางเดียว (Directional) กับแบบรอบทิศทาง (Omnidirectional) แตกต่างกันอย่างไร', 'อัตราขยายบ่งบอกความสามารถของเสาอากาศในการรวมพลังงานสัญญาณไปในทิศทางที่ต้องการเทียบกับเสาอากาศอ้างอิงในอุดมคติ เสาอากาศแบบทิศทางเดียวรวมพลังงานส่งไปในทิศทางที่แคบเฉพาะ ทำให้มีอัตราขยายสูงในทิศทางนั้นแต่รับส่งได้แคบ ส่วนเสาอากาศแบบรอบทิศทางกระจายพลังงานเท่าๆ กันในทุกทิศทางรอบตัว ทำให้มีอัตราขยายต่ำกว่าแต่ครอบคลุมพื้นที่กว้างกว่า', 'การเลือกใช้ขึ้นอยู่กับลักษณะการใช้งาน เช่น การเชื่อมโยงจุดต่อจุดระยะไกลมักใช้เสาอากาศทิศทางเดียวเพื่อประสิทธิภาพสูงสุด ในขณะที่จุดกระจายสัญญาณที่ต้องให้บริการผู้ใช้งานรอบด้านมักใช้เสาอากาศรอบทิศทาง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'อัตราขยายของเสาอากาศ (Antenna Gain) มีความหมายอย่างไร และเสาอากาศแบบทิศทางเดียว (Directional) กับแบบรอบทิศทาง (Omnidirectional) แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เขตเฟรสเนล (Fresnel Zone) ในการเชื่อมโยงสัญญาณไมโครเวฟระยะไกลมีความสำคัญอย่างไร', 'เป็นพื้นที่รูปทรงรีรอบเส้นตรงระหว่างเสาอากาศส่งและรับที่ต้องปราศจากสิ่งกีดขวาง เพื่อให้สัญญาณเดินทางไปถึงปลายทางได้อย่างมีประสิทธิภาพ แม้เส้นสายตาตรง (Line of Sight) ระหว่างสองจุดจะไม่มีสิ่งกีดขวาง แต่หากมีสิ่งกีดขวางเข้ามาในเขตเฟรสเนลบางส่วน ก็อาจทำให้เกิดการลดทอนสัญญาณเพิ่มเติมจากการเลี้ยวเบนได้', 'การออกแบบเสาสัญญาณสำหรับเชื่อมโยงไมโครเวฟระยะไกลจึงต้องคำนวณความสูงของเสาให้เพียงพอ ไม่เพียงแค่ให้เห็นเส้นสายตาตรงเท่านั้น แต่ต้องให้เขตเฟรสเนลส่วนใหญ่ปราศจากสิ่งกีดขวางด้วย เพื่อคุณภาพสัญญาณที่ดี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เขตเฟรสเนล (Fresnel Zone) ในการเชื่อมโยงสัญญาณไมโครเวฟระยะไกลมีความสำคัญอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การสูญเสียตามเส้นทาง (Path Loss) ของสัญญาณไร้สายคืออะไร และมีความสัมพันธ์กับระยะทางอย่างไร', 'คือการลดทอนของกำลังสัญญาณขณะเดินทางจากเสาอากาศส่งไปยังเสาอากาศรับ ซึ่งเกิดจากการกระจายพลังงานออกไปในพื้นที่กว้างขึ้นตามระยะทาง โดยทั่วไปในพื้นที่โล่งไม่มีสิ่งกีดขวาง กำลังสัญญาณจะลดลงตามสัดส่วนกำลังสองของระยะทาง (ตามกฎ Free Space Path Loss)', 'ในสภาพแวดล้อมจริงที่มีสิ่งกีดขวาง เช่น อาคารหรือต้นไม้ อัตราการลดทอนอาจสูงกว่าค่าทางทฤษฎีในพื้นที่โล่งอย่างมาก ทำให้การออกแบบระบบสื่อสารไร้สายในเมืองต้องพิจารณาปัจจัยด้านสภาพแวดล้อมเพิ่มเติมจากสูตรพื้นฐาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การสูญเสียตามเส้นทาง (Path Loss) ของสัญญาณไร้สายคืออะไร และมีความสัมพันธ์กับระยะทางอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เทคโนโลยี MIMO (Multiple Input Multiple Output) มีหลักการทำงานอย่างไรในการเพิ่มประสิทธิภาพระบบสื่อสารไร้สาย', 'ใช้เสาอากาศหลายต้นทั้งด้านส่งและด้านรับพร้อมกัน เพื่อส่งข้อมูลหลายชุดพร้อมกันผ่านเส้นทางสัญญาณที่แตกต่างกันในความถี่และเวลาเดียวกัน (Spatial Multiplexing) หรือเพื่อเพิ่มความน่าเชื่อถือของสัญญาณด้วยการส่งข้อมูลซ้ำผ่านหลายเส้นทาง (Diversity) ซึ่งช่วยเพิ่มอัตราการส่งข้อมูลหรือความน่าเชื่อถือของการเชื่อมต่อได้อย่างมีนัยสำคัญโดยไม่ต้องเพิ่มแบนด์วิดท์', 'เทคโนโลยีนี้เป็นพื้นฐานสำคัญของมาตรฐานการสื่อสารไร้สายสมัยใหม่หลายประเภท เช่น WiFi รุ่นใหม่และเครือข่ายโทรศัพท์เคลื่อนที่ 4G และ 5G ที่อาศัย MIMO เพื่อเพิ่มความจุของเครือข่ายให้รองรับผู้ใช้งานจำนวนมากพร้อมกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เทคโนโลยี MIMO (Multiple Input Multiple Output) มีหลักการทำงานอย่างไรในการเพิ่มประสิทธิภาพระบบสื่อสารไร้สาย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มาตรฐาน WiFi ที่ใช้กันแพร่หลาย เช่น 802.11n, 802.11ac และ 802.11ax มีการพัฒนาความสามารถแตกต่างกันอย่างไรในภาพรวม', 'แต่ละรุ่นมีการปรับปรุงเทคนิคการมอดูเลต การใช้ MIMO และการจัดการช่องความถี่ที่ซับซ้อนขึ้น ทำให้รองรับความเร็วในการส่งข้อมูลสูงขึ้นและรองรับจำนวนอุปกรณ์เชื่อมต่อพร้อมกันได้มากขึ้นในแต่ละรุ่นที่พัฒนาต่อเนื่องกันมา', 'มาตรฐานรุ่นใหม่ล่าสุดมักเน้นปรับปรุงประสิทธิภาพในสภาพแวดล้อมที่มีอุปกรณ์เชื่อมต่อหนาแน่น เช่น ในพื้นที่สาธารณะที่มีผู้ใช้งานจำนวนมากพร้อมกัน ซึ่งเป็นความท้าทายที่แตกต่างจากการเพิ่มความเร็วสูงสุดของการเชื่อมต่อเพียงจุดเดียวในมาตรฐานรุ่นก่อนหน้า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มาตรฐาน WiFi ที่ใช้กันแพร่หลาย เช่น 802.11n, 802.11ac และ 802.11ax มีการพัฒนาความสามารถแตกต่างกันอย่างไรในภาพรวม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครือข่ายโทรศัพท์เคลื่อนที่ 5G มีความแตกต่างที่สำคัญจากเครือข่าย 4G อย่างไรในเชิงสถาปัตยกรรมและความสามารถ', '5G ใช้ย่านความถี่ที่กว้างกว่ามาก รวมถึงย่านความถี่สูงมาก (Millimeter Wave) ที่ไม่เคยใช้ในเครือข่ายเคลื่อนที่มาก่อน ทำให้รองรับความเร็วสูงกว่าและความหน่วงเวลาต่ำกว่า 4G อย่างมีนัยสำคัญ อีกทั้งยังออกแบบให้รองรับการเชื่อมต่ออุปกรณ์จำนวนมหาศาลพร้อมกัน (Massive Machine Type Communication) ซึ่งเหมาะกับการใช้งานด้าน IoT', 'อย่างไรก็ตาม ความถี่สูงมากของ 5G มีระยะการครอบคลุมสัญญาณที่สั้นกว่าและถูกบดบังจากสิ่งกีดขวางได้ง่ายกว่าความถี่ต่ำที่ใช้ใน 4G ทำให้ต้องติดตั้งสถานีฐานจำนวนมากขึ้นและหนาแน่นกว่าเพื่อให้ครอบคลุมพื้นที่เดียวกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครือข่ายโทรศัพท์เคลื่อนที่ 5G มีความแตกต่างที่สำคัญจากเครือข่าย 4G อย่างไรในเชิงสถาปัตยกรรมและความสามารถ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เทคโนโลยี Bluetooth และ Zigbee ที่ใช้ในการสื่อสารระยะสั้นมีลักษณะการใช้งานที่แตกต่างกันอย่างไร', 'Bluetooth ออกแบบมาสำหรับการเชื่อมต่ออุปกรณ์ส่วนบุคคลระยะสั้น เช่น หูฟังไร้สายหรือเมาส์ไร้สาย มีอัตราการส่งข้อมูลค่อนข้างสูงแต่ใช้พลังงานมากกว่า ส่วน Zigbee ออกแบบมาสำหรับเครือข่ายเซนเซอร์ไร้สายที่ต้องการใช้พลังงานต่ำมากและสามารถทำงานเป็นเครือข่ายแบบตาข่าย (Mesh Network) ที่อุปกรณ์แต่ละตัวช่วยส่งต่อสัญญาณให้กันได้ เหมาะกับการใช้งานในระบบบ้านอัจฉริยะหรือระบบเซนเซอร์อุตสาหกรรมที่มีจุดเชื่อมต่อจำนวนมาก', 'การเลือกใช้เทคโนโลยีที่เหมาะสมขึ้นอยู่กับความต้องการเฉพาะของแอปพลิเคชัน เช่น หากต้องการอายุแบตเตอรี่ยาวนานมากสำหรับเซนเซอร์ที่ไม่ต้องเปลี่ยนแบตเตอรี่บ่อย Zigbee มักเป็นตัวเลือกที่เหมาะสมกว่า Bluetooth', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เทคโนโลยี Bluetooth และ Zigbee ที่ใช้ในการสื่อสารระยะสั้นมีลักษณะการใช้งานที่แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครือข่ายพลังงานต่ำระยะไกล (Low Power Wide Area Network, LPWAN) แตกต่างจากเทคโนโลยีไร้สายระยะสั้นทั่วไปอย่างไร', 'LPWAN ออกแบบมาให้ใช้พลังงานต่ำมากในขณะที่สามารถส่งสัญญาณได้ในระยะทางไกลกว่าเทคโนโลยีไร้สายระยะสั้นทั่วไปมาก แต่แลกกับอัตราการส่งข้อมูลที่ต่ำมาก เหมาะกับอุปกรณ์เซนเซอร์ที่ส่งข้อมูลปริมาณน้อยเป็นระยะๆ เช่น การอ่านค่ามิเตอร์อัจฉริยะ แทนที่จะส่งข้อมูลปริมาณมากต่อเนื่อง', 'เทคโนโลยีนี้ตอบโจทย์การใช้งาน IoT ที่ต้องการติดตั้งเซนเซอร์จำนวนมากกระจายในพื้นที่กว้างโดยไม่ต้องเปลี่ยนแบตเตอรี่บ่อย ซึ่งเป็นข้อจำกัดสำคัญของเทคโนโลยีไร้สายระยะสั้นทั่วไปที่ใช้พลังงานสูงกว่ามาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครือข่ายพลังงานต่ำระยะไกล (Low Power Wide Area Network, LPWAN) แตกต่างจากเทคโนโลยีไร้สายระยะสั้นทั่วไปอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'วงโคจรค้างฟ้า (Geostationary Orbit, GEO) ของดาวเทียมสื่อสารมีลักษณะพิเศษอย่างไร', 'เป็นวงโคจรที่อยู่สูงจากพื้นโลกในระดับที่ทำให้ดาวเทียมโคจรด้วยคาบเวลาเท่ากับการหมุนรอบตัวเองของโลกพอดี ทำให้ดาวเทียมปรากฏอยู่ในตำแหน่งคงที่เมื่อมองจากพื้นโลก เหมาะกับการสื่อสารที่ต้องการเสาอากาศภาคพื้นดินชี้ไปยังตำแหน่งคงที่โดยไม่ต้องปรับติดตามการเคลื่อนที่ของดาวเทียม', 'ข้อเสียของวงโคจรนี้คือความสูงที่มากทำให้เกิดความหน่วงเวลาในการสื่อสารค่อนข้างสูง เนื่องจากสัญญาณต้องเดินทางระยะทางไกลมากระหว่างพื้นโลกกับดาวเทียมและกลับมา ซึ่งมีผลกระทบต่อการใช้งานที่ต้องการการตอบสนองแบบเรียลไทม์', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'วงโคจรค้างฟ้า (Geostationary Orbit, GEO) ของดาวเทียมสื่อสารมีลักษณะพิเศษอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'วงโคจรระดับต่ำ (Low Earth Orbit, LEO) แตกต่างจากวงโคจรค้างฟ้าอย่างไร และมีข้อดีข้อเสียอย่างไรสำหรับการสื่อสาร', 'วงโคจรระดับต่ำอยู่ใกล้พื้นโลกมากกว่ามาก ทำให้ดาวเทียมโคจรรอบโลกด้วยความเร็วสูงและไม่คงตำแหน่งเมื่อเทียบกับพื้นโลก ข้อดีคือความหน่วงเวลาในการสื่อสารต่ำกว่าวงโคจรค้างฟ้ามาก เนื่องจากระยะทางที่สัญญาณต้องเดินทางสั้นกว่า แต่ข้อเสียคือต้องใช้ดาวเทียมจำนวนมากทำงานร่วมกันเป็นกลุ่มดาวเทียม (Constellation) เพื่อให้ครอบคลุมพื้นที่อย่างต่อเนื่อง เนื่องจากดาวเทียมแต่ละดวงเคลื่อนที่ผ่านพื้นที่หนึ่งอย่างรวดเร็ว', 'ระบบดาวเทียมอินเทอร์เน็ตความเร็วสูงสมัยใหม่หลายระบบเลือกใช้วงโคจรระดับต่ำ เพื่อให้ได้ความหน่วงเวลาที่ต่ำเพียงพอสำหรับการใช้งานที่ต้องการการตอบสนองรวดเร็ว แม้จะต้องลงทุนดาวเทียมจำนวนมากกว่าระบบวงโคจรค้างฟ้าก็ตาม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'วงโคจรระดับต่ำ (Low Earth Orbit, LEO) แตกต่างจากวงโคจรค้างฟ้าอย่างไร และมีข้อดีข้อเสียอย่างไรสำหรับการสื่อสาร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'วงโคจรระดับกลาง (Medium Earth Orbit, MEO) เหมาะกับการใช้งานประเภทใดเป็นพิเศษ', 'วงโคจรระดับกลางมักใช้กับระบบนำทางด้วยดาวเทียม (Satellite Navigation System) เช่น ระบบ GPS เนื่องจากความสูงระดับนี้ให้สมดุลที่เหมาะสมระหว่างพื้นที่ครอบคลุมสัญญาณที่กว้างพอสมควรและจำนวนดาวเทียมที่ต้องใช้ไม่มากเกินไปเมื่อเทียบกับวงโคจรระดับต่ำ ในขณะที่ยังคงมีความหน่วงเวลาที่ยอมรับได้สำหรับการคำนวณตำแหน่งแบบเรียลไทม์', 'ระบบนำทางด้วยดาวเทียมต้องอาศัยดาวเทียมหลายดวงในวงโคจรนี้ทำงานร่วมกันเป็นกลุ่ม เพื่อให้เครื่องรับสัญญาณภาคพื้นดินสามารถรับสัญญาณจากดาวเทียมอย่างน้อยสี่ดวงพร้อมกันได้ ซึ่งจำเป็นสำหรับการคำนวณตำแหน่งสามมิติและเวลาที่แม่นยำ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'วงโคจรระดับกลาง (Medium Earth Orbit, MEO) เหมาะกับการใช้งานประเภทใดเป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบนำทางด้วยดาวเทียมทั่วโลก (Global Navigation Satellite System, GNSS) คำนวณตำแหน่งของเครื่องรับสัญญาณบนพื้นโลกได้อย่างไร', 'อาศัยหลักการวัดเวลาที่สัญญาณเดินทางจากดาวเทียมแต่ละดวงมาถึงเครื่องรับ แล้วคำนวณระยะทางจากความเร็วแสงคูณด้วยเวลาที่วัดได้ เมื่อทราบระยะทางจากดาวเทียมอย่างน้อยสี่ดวงพร้อมตำแหน่งที่ทราบแน่นอนของดาวเทียมแต่ละดวง สามารถคำนวณตำแหน่งสามมิติของเครื่องรับและปรับแก้ค่าความคลาดเคลื่อนของนาฬิกาในเครื่องรับได้ด้วยวิธีการทางคณิตศาสตร์', 'ความแม่นยำของระบบขึ้นอยู่กับหลายปัจจัย เช่น ความแม่นยำของนาฬิกาบนดาวเทียม การหักเหของสัญญาณผ่านชั้นบรรยากาศ และจำนวนดาวเทียมที่มองเห็นได้ ณ ตำแหน่งและเวลานั้น ระบบสมัยใหม่มักใช้เทคนิคเสริมเพื่อเพิ่มความแม่นยำให้มากขึ้นกว่าความแม่นยำพื้นฐาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบนำทางด้วยดาวเทียมทั่วโลก (Global Navigation Satellite System, GNSS) คำนวณตำแหน่งของเครื่องรับสัญญาณบนพื้นโลกได้อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'สถานีภาคพื้นดินขนาดเล็กแบบ VSAT (Very Small Aperture Terminal) มีลักษณะและการใช้งานอย่างไร', 'เป็นสถานีภาคพื้นดินขนาดเล็กที่มีจานสัญญาณดาวเทียมขนาดค่อนข้างเล็ก ใช้ในการสื่อสารผ่านดาวเทียมสำหรับพื้นที่ห่างไกลที่โครงสร้างพื้นฐานการสื่อสารภาคพื้นดินเข้าถึงได้ยากหรือมีต้นทุนสูงเกินไป เช่น พื้นที่ชนบทห่างไกลหรือแท่นขุดเจาะน้ำมันกลางทะเล', 'แม้ต้นทุนต่อการติดตั้งอาจสูงกว่าการเชื่อมต่อภาคพื้นดินทั่วไปในพื้นที่ที่มีโครงสร้างพื้นฐานอยู่แล้ว แต่สำหรับพื้นที่ห่างไกลที่ไม่มีทางเลือกอื่น VSAT มักเป็นวิธีที่คุ้มค่าและรวดเร็วที่สุดในการเชื่อมต่อการสื่อสาร', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'สถานีภาคพื้นดินขนาดเล็กแบบ VSAT (Very Small Aperture Terminal) มีลักษณะและการใช้งานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การรบกวนคลื่นความถี่วิทยุ (Radio Frequency Interference, RFI) เกิดขึ้นได้จากสาเหตุใดบ้าง และมีผลกระทบต่อระบบสื่อสารไร้สายอย่างไร', 'เกิดได้จากหลายสาเหตุ เช่น อุปกรณ์อื่นที่ใช้ความถี่เดียวกันหรือใกล้เคียงกันทำงานอยู่ใกล้เคียง สัญญาณฮาร์มอนิกจากอุปกรณ์ไฟฟ้ากำลังหรืออุปกรณ์อิเล็กทรอนิกส์ หรือแม้แต่ปรากฏการณ์ทางธรรมชาติ เช่น พายุฟ้าคะนอง ผลกระทบคือทำให้คุณภาพสัญญาณลดลง เกิดความผิดพลาดในการรับส่งข้อมูล หรือในกรณีรุนแรงอาจทำให้การสื่อสารขาดหายไปโดยสิ้นเชิง', 'การจัดสรรและควบคุมการใช้คลื่นความถี่โดยหน่วยงานกำกับดูแลจึงมีความสำคัญอย่างมากในการป้องกันการรบกวนระหว่างผู้ใช้งานความถี่ต่างๆ ในพื้นที่เดียวกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การรบกวนคลื่นความถี่วิทยุ (Radio Frequency Interference, RFI) เกิดขึ้นได้จากสาเหตุใดบ้าง และมีผลกระทบต่อระบบสื่อสารไร้สายอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การจัดสรรคลื่นความถี่วิทยุ (Frequency Spectrum Allocation) โดยหน่วยงานกำกับดูแลของแต่ละประเทศมีความสำคัญอย่างไร', 'คลื่นความถี่วิทยุเป็นทรัพยากรที่มีจำกัดและใช้ร่วมกันได้ในพื้นที่เดียวกันเพียงจำกัด การจัดสรรที่เป็นระบบช่วยป้องกันการรบกวนกันระหว่างผู้ใช้งานหลายประเภท เช่น การกระจายเสียงวิทยุ โทรศัพท์เคลื่อนที่ การบิน และการทหาร ให้สามารถใช้งานคลื่นความถี่ในย่านต่างๆ ได้อย่างเป็นระเบียบโดยไม่รบกวนกัน', 'การจัดสรรคลื่นความถี่บางย่านสำหรับบริการโทรศัพท์เคลื่อนที่รุ่นใหม่ มักต้องผ่านกระบวนการประมูลหรือจัดสรรที่มีมูลค่าทางเศรษฐกิจสูง เนื่องจากเป็นทรัพยากรที่มีความต้องการสูงและมีจำกัด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การจัดสรรคลื่นความถี่วิทยุ (Frequency Spectrum Allocation) โดยหน่วยงานกำกับดูแลของแต่ละประเทศมีความสำคัญอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'คลื่นความถี่ที่ไม่ต้องขอใบอนุญาต (Unlicensed Spectrum) เช่น ย่านความถี่ที่ใช้ในระบบ WiFi ทั่วไป มีข้อดีและข้อจำกัดอย่างไร', 'ข้อดีคือผู้ใช้งานทั่วไปสามารถใช้งานอุปกรณ์ในย่านความถี่นี้ได้โดยไม่ต้องขอใบอนุญาตเฉพาะ ทำให้เทคโนโลยีที่ใช้ย่านความถี่นี้เข้าถึงได้ง่ายและมีต้นทุนต่ำ แต่ข้อจำกัดคือเนื่องจากผู้ใช้งานจำนวนมากสามารถใช้ความถี่เดียวกันได้พร้อมกันโดยไม่มีการควบคุมส่วนกลาง จึงมีความเสี่ยงสูงต่อการรบกวนกันเองระหว่างอุปกรณ์หลายชนิดที่ใช้ย่านความถี่เดียวกันในพื้นที่เดียวกัน', 'ในพื้นที่ที่มีอุปกรณ์ไร้สายหนาแน่นมาก เช่น อาคารสำนักงานหรืออพาร์ตเมนต์ที่มีเครือข่าย WiFi หลายเครือข่ายทับซ้อนกัน คุณภาพสัญญาณอาจลดลงอย่างมีนัยสำคัญจากการรบกวนกันเองในย่านความถี่ที่ไม่ต้องขอใบอนุญาตนี้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'คลื่นความถี่ที่ไม่ต้องขอใบอนุญาต (Unlicensed Spectrum) เช่น ย่านความถี่ที่ใช้ในระบบ WiFi ทั่วไป มีข้อดีและข้อจำกัดอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดสัญญาณไมโครเวฟความถี่สูงจึงเหมาะสำหรับการเชื่อมโยงแบบจุดต่อจุด (Point-to-Point Link) มากกว่าการกระจายสัญญาณครอบคลุมพื้นที่กว้าง', 'เพราะความยาวคลื่นของสัญญาณไมโครเวฟที่สั้นทำให้สามารถออกแบบเสาอากาศที่มีอัตราขยายสูงและรวมพลังงานเป็นลำแคบได้ง่าย เหมาะกับการส่งพลังงานสัญญาณไปยังจุดเป้าหมายที่ทราบตำแหน่งแน่นอนอย่างมีประสิทธิภาพสูง แต่ไม่เหมาะกับการกระจายสัญญาณให้ครอบคลุมพื้นที่กว้างเนื่องจากคลื่นเดินทางเป็นเส้นตรงและถูกบดบังจากสิ่งกีดขวางได้ง่าย', 'การเชื่อมโยงไมโครเวฟจุดต่อจุดจึงนิยมใช้สำหรับการเชื่อมโยงสัญญาณระหว่างสถานีฐานโทรศัพท์เคลื่อนที่หรือระหว่างอาคารในเมือง ที่ทราบตำแหน่งปลายทางแน่นอนและต้องการความจุสูงในการเชื่อมโยง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดสัญญาณไมโครเวฟความถี่สูงจึงเหมาะสำหรับการเชื่อมโยงแบบจุดต่อจุด (Point-to-Point Link) มากกว่าการกระจายสัญญาณครอบคลุมพื้นที่กว้าง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งเสาสัญญาณโทรศัพท์เคลื่อนที่ (Cell Tower) ในเขตเมืองจึงมักมีระยะห่างระหว่างสถานีฐานที่ใกล้กว่าในพื้นที่ชนบท', 'เพราะในเขตเมืองมีความหนาแน่นของผู้ใช้งานสูงมาก แต่ละสถานีฐานมีความจุจำกัดในการรองรับจำนวนผู้ใช้งานพร้อมกัน การติดตั้งสถานีฐานถี่ขึ้นช่วยแบ่งภาระผู้ใช้งานให้กระจายไปยังสถานีฐานหลายแห่ง ทำให้แต่ละสถานีรองรับผู้ใช้งานในพื้นที่ที่เล็กลง เพิ่มความจุโดยรวมของเครือข่ายในพื้นที่นั้น', 'ในทางกลับกัน พื้นที่ชนบทที่มีผู้ใช้งานเบาบาง มักเน้นการวางสถานีฐานให้ครอบคลุมพื้นที่กว้างที่สุดเท่าที่จะทำได้ต่อสถานีหนึ่ง เนื่องจากไม่มีข้อจำกัดด้านความจุรองรับผู้ใช้งานมากเท่าในเมือง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งเสาสัญญาณโทรศัพท์เคลื่อนที่ (Cell Tower) ในเขตเมืองจึงมักมีระยะห่างระหว่างสถานีฐานที่ใกล้กว่าในพื้นที่ชนบท'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เทคโนโลยี Beamforming ในระบบสื่อสารไร้สายสมัยใหม่มีหลักการทำงานอย่างไร', 'ใช้เสาอากาศหลายต้นควบคุมเฟสของสัญญาณที่ส่งออกจากแต่ละต้นอย่างแม่นยำ เพื่อให้สัญญาณจากเสาอากาศทั้งหมดรวมกันเสริมแรงกัน (Constructive Interference) ในทิศทางที่ต้องการส่งไปยังผู้ใช้งานเฉพาะราย ในขณะที่หักล้างกัน (Destructive Interference) ในทิศทางอื่นที่ไม่ต้องการ ทำให้สามารถโฟกัสพลังงานสัญญาณไปยังผู้ใช้งานแต่ละรายได้อย่างมีประสิทธิภาพ', 'เทคโนโลยีนี้ช่วยเพิ่มความแรงของสัญญาณที่ผู้ใช้งานได้รับและลดการรบกวนต่อผู้ใช้งานรายอื่นในบริเวณใกล้เคียง เป็นเทคนิคสำคัญที่ใช้ในระบบเสาอากาศแบบ Massive MIMO ของเครือข่าย 5G เพื่อเพิ่มความจุของเครือข่ายในพื้นที่ที่มีผู้ใช้งานหนาแน่น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เทคโนโลยี Beamforming ในระบบสื่อสารไร้สายสมัยใหม่มีหลักการทำงานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการสื่อสารผ่านดาวเทียมวงโคจรค้างฟ้าจึงไม่เหมาะกับการใช้งานที่ต้องการความหน่วงเวลาต่ำมาก เช่น การเล่นเกมออนไลน์แบบเรียลไทม์', 'เพราะความสูงของวงโคจรค้างฟ้าที่อยู่ห่างจากพื้นโลกมาก ทำให้สัญญาณต้องเดินทางระยะทางไกลมากในการไปกลับระหว่างพื้นโลกกับดาวเทียม แม้สัญญาณจะเดินทางด้วยความเร็วแสง แต่ระยะทางที่ไกลมากนี้ก็ยังคงสร้างความหน่วงเวลาที่สังเกตได้ชัดเจน ซึ่งอาจสูงกว่าความหน่วงเวลาของการเชื่อมต่ออินเทอร์เน็ตภาคพื้นดินทั่วไปหลายเท่าตัว', 'นี่เป็นเหตุผลสำคัญที่ระบบดาวเทียมอินเทอร์เน็ตความเร็วสูงรุ่นใหม่หันมาใช้วงโคจรระดับต่ำแทน เพื่อลดความหน่วงเวลาให้อยู่ในระดับที่ยอมรับได้สำหรับการใช้งานที่ต้องการการตอบสนองรวดเร็ว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการสื่อสารผ่านดาวเทียมวงโคจรค้างฟ้าจึงไม่เหมาะกับการใช้งานที่ต้องการความหน่วงเวลาต่ำมาก เช่น การเล่นเกมออนไลน์แบบเรียลไทม์'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบสื่อสารผ่านดาวเทียมจึงต้องคำนวณงบประมาณการเชื่อมโยงสัญญาณ (Link Budget) อย่างละเอียด', 'เพราะสัญญาณต้องเดินทางระยะทางไกลมากผ่านชั้นบรรยากาศและสภาวะอวกาศ ซึ่งมีการลดทอนสัญญาณจากหลายปัจจัย เช่น การกระจายพลังงานตามระยะทาง การดูดกลืนของชั้นบรรยากาศ และสภาพอากาศ เช่น ฝนตกหนักในบางย่านความถี่ การคำนวณ Link Budget ช่วยยืนยันว่ากำลังส่งสัญญาณและความไวของเครื่องรับเพียงพอที่จะรักษาคุณภาพการสื่อสารได้ในทุกสภาวะที่คาดว่าจะเกิดขึ้น', 'การคำนวณนี้ต้องพิจารณาปัจจัยหลายด้านร่วมกัน ทั้งกำลังส่งสัญญาณ อัตราขยายเสาอากาศทั้งสองด้าน การลดทอนตามระยะทางและสภาพอากาศ และค่าสัญญาณรบกวนของระบบ เพื่อให้ได้อัตราส่วนสัญญาณต่อสัญญาณรบกวนที่เพียงพอสำหรับคุณภาพการสื่อสารที่ต้องการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบสื่อสารผ่านดาวเทียมจึงต้องคำนวณงบประมาณการเชื่อมโยงสัญญาณ (Link Budget) อย่างละเอียด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การลดทอนสัญญาณจากฝน (Rain Fade) ส่งผลกระทบต่อการสื่อสารผ่านดาวเทียมอย่างไร และเหตุใดจึงรุนแรงมากขึ้นในความถี่สูง', 'หยดน้ำฝนสามารถดูดกลืนและกระเจิงพลังงานของคลื่นสัญญาณที่เดินทางผ่าน ทำให้เกิดการลดทอนสัญญาณเพิ่มเติมในช่วงที่มีฝนตกหนัก ผลกระทบนี้รุนแรงมากขึ้นตามความถี่ที่สูงขึ้น เนื่องจากความยาวคลื่นที่สั้นลงมีขนาดใกล้เคียงกับขนาดของหยดน้ำฝนมากขึ้น ทำให้เกิดการกระเจิงสัญญาณได้มากขึ้น', 'ระบบสื่อสารดาวเทียมที่ใช้ความถี่สูง จึงมักต้องออกแบบให้มีกำลังส่งสัญญาณสำรอง (Rain Fade Margin) เผื่อไว้สำหรับสภาวะฝนตกหนัก เพื่อรักษาคุณภาพการสื่อสารให้ยังคงอยู่ในเกณฑ์ที่ยอมรับได้แม้ในสภาพอากาศที่ไม่เอื้ออำนวย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การลดทอนสัญญาณจากฝน (Rain Fade) ส่งผลกระทบต่อการสื่อสารผ่านดาวเทียมอย่างไร และเหตุใดจึงรุนแรงมากขึ้นในความถี่สูง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดสถานีภาคพื้นดินที่รับส่งสัญญาณดาวเทียมจึงต้องมีระบบติดตามดาวเทียม (Tracking System) สำหรับดาวเทียมในวงโคจรระดับต่ำ แต่ไม่จำเป็นสำหรับดาวเทียมวงโคจรค้างฟ้า', 'เพราะดาวเทียมในวงโคจรระดับต่ำเคลื่อนที่ผ่านท้องฟ้าอย่างรวดเร็วเมื่อมองจากพื้นโลก เสาอากาศภาคพื้นดินจึงต้องปรับมุมติดตามตำแหน่งของดาวเทียมอย่างต่อเนื่องเพื่อรักษาการเชื่อมต่อ ในขณะที่ดาวเทียมวงโคจรค้างฟ้าปรากฏอยู่ในตำแหน่งคงที่เมื่อมองจากพื้นโลก เสาอากาศภาคพื้นดินจึงชี้ไปยังตำแหน่งคงที่ได้โดยไม่ต้องปรับมุมตลอดเวลา', 'ระบบติดตามดาวเทียมที่แม่นยำเป็นความท้าทายทางวิศวกรรมเพิ่มเติมสำหรับระบบดาวเทียมวงโคจรต่ำ ซึ่งอาจต้องใช้เสาอากาศหลายชุดสลับการทำงานเพื่อรักษาการเชื่อมต่อต่อเนื่องขณะที่ดาวเทียมดวงหนึ่งกำลังจะเคลื่อนพ้นขอบฟ้าและอีกดวงกำลังปรากฏขึ้นมาแทน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดสถานีภาคพื้นดินที่รับส่งสัญญาณดาวเทียมจึงต้องมีระบบติดตามดาวเทียม (Tracking System) สำหรับดาวเทียมในวงโคจรระดับต่ำ แต่ไม่จำเป็นสำหรับดาวเทียมวงโคจรค้างฟ้า'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการออกแบบระบบสื่อสารไร้สายในอาคาร (In-building Wireless System) จึงอาจจำเป็นต้องมีระบบขยายสัญญาณเสาอากาศกระจาย (Distributed Antenna System, DAS)', 'เพราะโครงสร้างอาคาร โดยเฉพาะวัสดุก่อสร้างสมัยใหม่ เช่น กระจกเคลือบโลหะหรือคอนกรีตเสริมเหล็กหนา อาจลดทอนสัญญาณจากสถานีฐานภายนอกอย่างมาก ทำให้สัญญาณภายในอาคารอ่อนเกินกว่าจะใช้งานได้ดี ระบบ DAS ช่วยรับสัญญาณจากภายนอกหรือแหล่งกำเนิดสัญญาณเฉพาะ แล้วกระจายผ่านเสาอากาศหลายจุดภายในอาคารเพื่อให้ครอบคลุมพื้นที่ทั้งหมดอย่างทั่วถึง', 'ระบบนี้มีความสำคัญเป็นพิเศษในอาคารขนาดใหญ่ เช่น ห้างสรรพสินค้าหรือสนามบิน ที่ต้องการสัญญาณโทรศัพท์เคลื่อนที่คุณภาพดีทั่วทั้งพื้นที่ รวมถึงในพื้นที่ที่มีความสำคัญด้านความปลอดภัย เช่น ระบบสื่อสารสำหรับหน่วยดับเพลิงที่ต้องใช้งานได้แม้อยู่ลึกภายในอาคาร', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการออกแบบระบบสื่อสารไร้สายในอาคาร (In-building Wireless System) จึงอาจจำเป็นต้องมีระบบขยายสัญญาณเสาอากาศกระจาย (Distributed Antenna System, DAS)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวางแผนความครอบคลุมสัญญาณไร้สาย (Coverage Planning) จึงต้องพิจารณาทั้งพื้นที่ภายนอกและภายในอาคารแยกกัน', 'เพราะลักษณะการลดทอนสัญญาณและสิ่งกีดขวางในพื้นที่ภายนอกและภายในอาคารแตกต่างกันอย่างมาก การคำนวณความครอบคลุมโดยพิจารณาเพียงพื้นที่ภายนอกอาจไม่สะท้อนถึงคุณภาพสัญญาณจริงที่ผู้ใช้งานได้รับเมื่ออยู่ภายในอาคาร ซึ่งมักมีการลดทอนสัญญาณเพิ่มเติมจากผนังและโครงสร้างอาคาร', 'การวางแผนเครือข่ายที่ดีจึงมักใช้แบบจำลองการลดทอนสัญญาณที่แตกต่างกันสำหรับสภาพแวดล้อมภายนอกและภายในอาคาร และในบางกรณีอาจต้องพิจารณาติดตั้งระบบเสริมสัญญาณภายในอาคารแยกต่างหากตามที่กล่าวถึงข้างต้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวางแผนความครอบคลุมสัญญาณไร้สาย (Coverage Planning) จึงต้องพิจารณาทั้งพื้นที่ภายนอกและภายในอาคารแยกกัน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดหน่วยงานกำกับดูแลด้านโทรคมนาคมจึงต้องกำหนดขีดจำกัดกำลังส่งสัญญาณสูงสุด (Maximum Transmit Power) สำหรับอุปกรณ์ไร้สายแต่ละประเภท', 'เพื่อจำกัดขอบเขตการรบกวนที่อุปกรณ์แต่ละเครื่องอาจก่อให้เกิดต่อผู้ใช้งานความถี่เดียวกันหรือใกล้เคียงในพื้นที่อื่น หากไม่มีขีดจำกัดกำลังส่ง อุปกรณ์ที่ส่งสัญญาณแรงเกินไปอาจรบกวนการสื่อสารของผู้ใช้งานรายอื่นในระยะทางไกลเกินความจำเป็น ทำให้การใช้ทรัพยากรความถี่ที่มีจำกัดไม่มีประสิทธิภาพ', 'ขีดจำกัดกำลังส่งยังเกี่ยวข้องกับความปลอดภัยด้านการได้รับรังสีคลื่นแม่เหล็กไฟฟ้าของมนุษย์ (Human Exposure to Electromagnetic Field) ซึ่งเป็นอีกเหตุผลสำคัญที่หน่วยงานกำกับดูแลต้องกำหนดขีดจำกัดที่เหมาะสมสำหรับอุปกรณ์แต่ละประเภท', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดหน่วยงานกำกับดูแลด้านโทรคมนาคมจึงต้องกำหนดขีดจำกัดกำลังส่งสัญญาณสูงสุด (Maximum Transmit Power) สำหรับอุปกรณ์ไร้สายแต่ละประเภท'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบสื่อสารดาวเทียมสำรอง (Satellite Backup Link) สำหรับสถานที่สำคัญ จึงยังคงมีความจำเป็นแม้ในปัจจุบันที่มีโครงสร้างพื้นฐานเส้นใยแก้วนำแสงครอบคลุมกว้างขวางแล้ว', 'เพราะการสื่อสารผ่านดาวเทียมไม่ขึ้นอยู่กับโครงสร้างพื้นฐานภาคพื้นดินที่อาจเสียหายจากภัยพิบัติ เช่น แผ่นดินไหว น้ำท่วม หรือความเสียหายทางกายภาพต่อสายเคเบิล ทำให้เป็นทางเลือกสำรองที่มีความเป็นอิสระจากความเสี่ยงที่อาจกระทบโครงสร้างพื้นฐานภาคพื้นดินพร้อมกันในเหตุการณ์เดียว', 'สถานที่ที่มีความสำคัญสูง เช่น ศูนย์ควบคุมภัยพิบัติหรือหน่วยงานความมั่นคง จึงมักมีระบบสื่อสารดาวเทียมสำรองไว้เสมอ แม้จะมีการเชื่อมต่อหลักผ่านเส้นใยแก้วนำแสงคุณภาพสูงอยู่แล้วก็ตาม เพื่อความมั่นใจในความต่อเนื่องของการสื่อสารในสถานการณ์ฉุกเฉินร้ายแรง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบสื่อสารดาวเทียมสำรอง (Satellite Backup Link) สำหรับสถานที่สำคัญ จึงยังคงมีความจำเป็นแม้ในปัจจุบันที่มีโครงสร้างพื้นฐานเส้นใยแก้วนำแสงครอบคลุมกว้างขวางแล้ว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการติดตั้งเสาอากาศดาวเทียมภาคพื้นดิน จึงต้องพิจารณาลดโอกาสการรบกวนจากดาวเทียมดวงอื่นที่อยู่ใกล้เคียงในวงโคจรเดียวกัน (Adjacent Satellite Interference)', 'เพราะดาวเทียมวงโคจรค้างฟ้าหลายดวงถูกจัดวางในตำแหน่งที่ค่อนข้างใกล้กันตามแนววงโคจร เสาอากาศภาคพื้นดินที่มีลำแสงกว้างเกินไปอาจรับหรือส่งสัญญาณไปกระทบกับดาวเทียมข้างเคียงโดยไม่ตั้งใจ ทำให้เกิดการรบกวนซึ่งกันและกันระหว่างระบบที่ใช้ดาวเทียมต่างดวง', 'การออกแบบเสาอากาศให้มีลำแสงแคบเพียงพอและติดตั้งด้วยความแม่นยำสูง เป็นข้อกำหนดสำคัญที่ผู้ให้บริการดาวเทียมมักกำหนดไว้อย่างเข้มงวด เพื่อป้องกันปัญหาการรบกวนระหว่างระบบต่างๆ ที่ใช้ดาวเทียมในวงโคจรใกล้เคียงกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการติดตั้งเสาอากาศดาวเทียมภาคพื้นดิน จึงต้องพิจารณาลดโอกาสการรบกวนจากดาวเทียมดวงอื่นที่อยู่ใกล้เคียงในวงโคจรเดียวกัน (Adjacent Satellite Interference)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการสื่อสารดาวเทียมแบบ Ku-band และ Ka-band ที่ใช้ความถี่สูงกว่า C-band จึงมีข้อดีด้านขนาดอุปกรณ์แต่มีความอ่อนไหวต่อสภาพอากาศมากกว่า', 'ความถี่ที่สูงกว่าทำให้ความยาวคลื่นสั้นลง ซึ่งช่วยให้สามารถออกแบบจานสัญญาณขนาดเล็กลงในขณะที่ยังคงอัตราขยายที่เพียงพอ ทำให้อุปกรณ์ภาคพื้นดินมีขนาดกะทัดรัดและต้นทุนต่ำกว่า แต่ในขณะเดียวกันความยาวคลื่นที่สั้นลงก็มีความไวต่อการลดทอนจากฝนและความชื้นในบรรยากาศมากขึ้นตามที่กล่าวถึงในหัวข้อ Rain Fade ก่อนหน้า', 'การเลือกย่านความถี่ที่เหมาะสมสำหรับระบบดาวเทียมจึงต้องพิจารณาสมดุลระหว่างขนาดและต้นทุนอุปกรณ์ กับความน่าเชื่อถือของสัญญาณในสภาพอากาศต่างๆ ของพื้นที่ที่ใช้งาน โดยเฉพาะประเทศเขตร้อนที่มีฝนตกชุกอาจต้องพิจารณาปัจจัยนี้เป็นพิเศษ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการสื่อสารดาวเทียมแบบ Ku-band และ Ka-band ที่ใช้ความถี่สูงกว่า C-band จึงมีข้อดีด้านขนาดอุปกรณ์แต่มีความอ่อนไหวต่อสภาพอากาศมากกว่า'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรออกแบบระบบสื่อสารไร้สายจึงต้องพิจารณาผลกระทบต่อสิ่งแวดล้อมและสุขภาพจากคลื่นแม่เหล็กไฟฟ้า แม้ระดับพลังงานที่ใช้งานจริงจะต่ำกว่าเกณฑ์มาตรฐานความปลอดภัยมากก็ตาม', 'เพราะแม้หลักฐานทางวิทยาศาสตร์ปัจจุบันจะยืนยันว่าระดับการได้รับคลื่นแม่เหล็กไฟฟ้าจากอุปกรณ์สื่อสารทั่วไปที่เป็นไปตามมาตรฐานมีความปลอดภัย แต่ความกังวลของสาธารณชนเกี่ยวกับผลกระทบต่อสุขภาพยังคงเป็นประเด็นที่ต้องให้ความสำคัญ การสื่อสารข้อมูลที่ถูกต้องและโปร่งใสเกี่ยวกับมาตรฐานความปลอดภัยที่ใช้ในการออกแบบระบบ ช่วยสร้างความเชื่อมั่นและลดความขัดแย้งกับชุมชนในการติดตั้งโครงสร้างพื้นฐานสื่อสาร', 'การพิจารณาปัจจัยด้านการยอมรับของสังคม (Social Acceptance) ควบคู่ไปกับความถูกต้องทางเทคนิค จึงเป็นส่วนสำคัญของการวางแผนติดตั้งโครงสร้างพื้นฐานสื่อสารไร้สายในพื้นที่ที่มีชุมชนอาศัยอยู่ ไม่ใช่เพียงการปฏิบัติตามมาตรฐานทางเทคนิคเพียงอย่างเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรออกแบบระบบสื่อสารไร้สายจึงต้องพิจารณาผลกระทบต่อสิ่งแวดล้อมและสุขภาพจากคลื่นแม่เหล็กไฟฟ้า แม้ระดับพลังงานที่ใช้งานจริงจะต่ำกว่าเกณฑ์มาตรฐานความปลอดภัยมากก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดแนวโน้มการพัฒนาเทคโนโลยีสื่อสารไร้สายในอนาคต จึงมุ่งไปสู่การบูรณาการระหว่างเครือข่ายภาคพื้นดินและเครือข่ายดาวเทียมเข้าด้วยกัน (Non-Terrestrial Network Integration)', 'เพราะแต่ละเทคโนโลยีมีจุดแข็งและจุดอ่อนที่แตกต่างกัน เครือข่ายภาคพื้นดินให้ความจุสูงและความหน่วงเวลาต่ำในพื้นที่ที่มีโครงสร้างพื้นฐานหนาแน่น ในขณะที่เครือข่ายดาวเทียมให้ความครอบคลุมพื้นที่กว้างรวมถึงพื้นที่ห่างไกลที่เครือข่ายภาคพื้นดินเข้าไม่ถึง การบูรณาการทั้งสองเทคโนโลยีเข้าด้วยกันช่วยให้ผู้ใช้งานได้รับบริการสื่อสารที่ต่อเนื่องไม่ว่าจะอยู่ในพื้นที่ใด โดยระบบสามารถสลับใช้เทคโนโลยีที่เหมาะสมที่สุดตามสภาพแวดล้อมนั้นได้โดยอัตโนมัติ', 'แนวโน้มนี้สะท้อนถึงทิศทางการพัฒนามาตรฐานการสื่อสารเคลื่อนที่รุ่นถัดไป ที่เริ่มออกแบบให้รองรับการเชื่อมต่อกับดาวเทียมโดยตรงเป็นส่วนหนึ่งของมาตรฐานเครือข่ายเดียวกัน แทนที่จะเป็นระบบแยกต่างหากที่ทำงานอิสระจากกันเหมือนในอดีต', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดแนวโน้มการพัฒนาเทคโนโลยีสื่อสารไร้สายในอนาคต จึงมุ่งไปสู่การบูรณาการระหว่างเครือข่ายภาคพื้นดินและเครือข่ายดาวเทียมเข้าด้วยกัน (Non-Terrestrial Network Integration)'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'wireless_satellite'
group by c.name_th;
